package userenv

import (
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"
)

const manifest = `{"requirements": [
  {"id": "a", "kind": "env", "name": "AGENT_REPL_PERSISTENT_WIFI_HOTSPOT"},
  {"id": "b", "kind": "program", "name": "go"},
  {"id": "c", "kind": "env", "name": "MULTI_REPO_ROOT"}
]}`

const envFile = `;; -*- mode: lisp-interaction; -*-
;; This file was auto-generated by ` + "`doom env'" + `.

("PATH=/bin"
 "AGENT_REPL_PERSISTENT_WIFI_HOTSPOT=Dodge's iPhone"
 "QUOTED=say \"hi\" \\ there"
 "MULTI_REPO_ROOT=/from/file")
`

// write puts body at name under a temporary directory and answers its path.
func write(t *testing.T, name, body string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), name)
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
	return path
}

func TestSettingNamesAreTheManifestsEnvRequirements(t *testing.T) {
	// Act
	got, err := SettingNames(write(t, "requirements.json", manifest))

	// Assert
	if err != nil || !slices.Equal(got, []string{"AGENT_REPL_PERSISTENT_WIFI_HOTSPOT", "MULTI_REPO_ROOT"}) {
		t.Fatalf("SettingNames = %v, %v; want the two env requirements", got, err)
	}
}

func TestSettingNamesFailures(t *testing.T) {
	tests := []struct {
		name, body, want string
	}{
		{name: "not json", body: "{", want: "is not a requirements manifest"},
		{name: "an env requirement with no name", body: `{"requirements": [{"id": "x", "kind": "env"}]}`, want: "with no name"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// Act
			_, err := SettingNames(write(t, "requirements.json", tt.body))

			// Assert
			if err == nil || !strings.Contains(err.Error(), tt.want) {
				t.Fatalf("SettingNames err = %v, want %q", err, tt.want)
			}
		})
	}
}

func TestParseEnvFileReadsEveryEntryWithItsEscapes(t *testing.T) {
	// Act
	got, err := ParseEnvFile([]byte(envFile))

	// Assert
	if err != nil {
		t.Fatal(err)
	}
	if got["AGENT_REPL_PERSISTENT_WIFI_HOTSPOT"] != "Dodge's iPhone" || got["QUOTED"] != `say "hi" \ there` || got["PATH"] != "/bin" {
		t.Fatalf("ParseEnvFile = %v", got)
	}
}

// doomHeader is the header `doom env' writes, parentheses and all.
const doomHeader = `;; -*- mode: lisp-interaction; coding: utf-8-unix; -*-
;; ---------------------------------------------------------------------------
;; This file was auto-generated by ` + "`doom env'" + `. It contains a list of environment
;; variables scraped from your default shell (based on your settings for
;; ` + "`doom-env-allow' and `doom-env-deny'" + `).
;;
;; It is NOT safe to edit this file. Changes will be overwritten next time you
;; run 'doom sync'. To create a safe-to-edit envvar file use:
;;
;;   doom env -o ~/.doom.d/myenv
;;
;; And load it with (doom-load-envvars-file "~/.doom.d/myenv").

`

func TestParseEnvFileReadsTheListPastDoomsHeader(t *testing.T) {
	// Arrange
	body := doomHeader + `("A=1" "B=two")` + "\n"

	// Act
	got, err := ParseEnvFile([]byte(body))

	// Assert
	if err != nil || len(got) != 2 || got["A"] != "1" || got["B"] != "two" {
		t.Fatalf("ParseEnvFile = %v, %v; want both entries past the header's parentheses", got, err)
	}
}

func TestParseEnvFileFailures(t *testing.T) {
	tests := []struct {
		name, body, want string
	}{
		{name: "no list", body: ";; nothing\n", want: "no list of variables"},
		{name: "no list after a comment that holds a parenthesis", body: ";; (based on your settings)\n", want: "no list of variables"},
		{name: "a comment that never ends its line", body: ";; nothing", want: "no list of variables"},
		{name: "text before the list", body: "x (\"A=1\")", want: "before its list of variables"},
		{name: "an unterminated string", body: `("A=1`, want: "ends inside a string"},
		{name: "an unterminated list", body: `("A=1"`, want: "never ends"},
		{name: "an entry that is not NAME=VALUE", body: `("A")`, want: "is not NAME=VALUE"},
		{name: "a stray token", body: `("A=1" x)`, want: "where a string or the list's end belongs"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// Act
			_, err := ParseEnvFile([]byte(tt.body))

			// Assert
			if err == nil || !strings.Contains(err.Error(), tt.want) {
				t.Fatalf("ParseEnvFile err = %v, want %q", err, tt.want)
			}
		})
	}
}

func TestRefreshTakesEachSettingFromTheFile(t *testing.T) {
	tests := []struct {
		name    string
		environ []string
		file    map[string]string
		want    []string
	}{
		{name: "a setting added after start is added",
			environ: []string{"PATH=/bin"}, file: map[string]string{"HOTSPOT": "phone"},
			want: []string{"PATH=/bin", "HOTSPOT=phone"}},
		{name: "a changed setting takes the file's value",
			environ: []string{"HOTSPOT=old", "PATH=/bin"}, file: map[string]string{"HOTSPOT": "new"},
			want: []string{"PATH=/bin", "HOTSPOT=new"}},
		{name: "a setting the file no longer has is removed",
			environ: []string{"HOTSPOT=old", "PATH=/bin"}, file: map[string]string{},
			want: []string{"PATH=/bin"}},
		{name: "a variable that is no setting is left alone, even when the file has it",
			environ: []string{"PATH=/bin"}, file: map[string]string{"PATH": "/elsewhere"},
			want: []string{"PATH=/bin"}},
		{name: "a setting Emacs stated is Emacs's",
			environ: []string{EmacsStated + "=HOTSPOT", "HOTSPOT=emacs"}, file: map[string]string{"HOTSPOT": "file"},
			want: []string{EmacsStated + "=HOTSPOT", "HOTSPOT=emacs"}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// Act
			got := Refresh(tt.environ, []string{"HOTSPOT"}, tt.file)

			// Assert
			if !slices.Equal(got, tt.want) {
				t.Fatalf("Refresh = %v, want %v", got, tt.want)
			}
		})
	}
}

func TestSuccessorRefreshesFromTheEnvFileEmacsNamed(t *testing.T) {
	// Arrange
	file := write(t, "env", envFile)
	environ := []string{EnvFile + "=" + file, "PATH=/bin", EmacsStated + "=MULTI_REPO_ROOT", "MULTI_REPO_ROOT=/from/emacs"}

	// Act
	got, changed, err := Successor(environ, write(t, "requirements.json", manifest))

	// Assert
	if err != nil {
		t.Fatal(err)
	}
	if !slices.Contains(got, "AGENT_REPL_PERSISTENT_WIFI_HOTSPOT=Dodge's iPhone") || !slices.Contains(got, "MULTI_REPO_ROOT=/from/emacs") {
		t.Fatalf("Successor = %v, want the file's hotspot and Emacs's root", got)
	}
	if len(changed) != 1 || changed[0] != (Change{Name: "AGENT_REPL_PERSISTENT_WIFI_HOTSPOT", Now: "Dodge's iPhone"}) {
		t.Fatalf("changed = %+v, want the hotspot added", changed)
	}
}

func TestSuccessorOfADaemonEmacsDidNotStartInheritsItsEnvironment(t *testing.T) {
	// Arrange
	environ := []string{"PATH=/bin", "HOTSPOT=kept"}

	// Act
	got, changed, err := Successor(environ, "/no/manifest/needed")

	// Assert
	if err != nil || !slices.Equal(got, environ) || changed != nil {
		t.Fatalf("Successor = %v, %v, %v; want the environment unchanged", got, changed, err)
	}
}

func TestSuccessorFailures(t *testing.T) {
	tests := []struct {
		name     string
		envFile  func(t *testing.T) string
		manifest func(t *testing.T) string
		want     string
	}{
		{name: "an env file that is gone",
			envFile:  func(t *testing.T) string { return filepath.Join(t.TempDir(), "gone") },
			manifest: func(t *testing.T) string { return write(t, "requirements.json", manifest) },
			want:     "read the env file"},
		{name: "an env file that does not parse",
			envFile:  func(t *testing.T) string { return write(t, "env", `("A`) },
			manifest: func(t *testing.T) string { return write(t, "requirements.json", manifest) },
			want:     "ends inside a string"},
		{name: "a manifest that is gone",
			envFile:  func(t *testing.T) string { return write(t, "env", envFile) },
			manifest: func(t *testing.T) string { return filepath.Join(t.TempDir(), "gone.json") },
			want:     "read the requirements manifest"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// Act
			got, _, err := Successor([]string{EnvFile + "=" + tt.envFile(t)}, tt.manifest(t))

			// Assert
			if err == nil || got != nil || !strings.Contains(err.Error(), tt.want) {
				t.Fatalf("Successor = %v, %v; want no environment and %q", got, err, tt.want)
			}
		})
	}
}
